use tree_sitter::Parser;

fn dump(node: tree_sitter::Node, source: &str, depth: usize) {
    let text: String = if node.child_count() == 0 {
        format!(" {:?}", &source[node.start_byte()..node.end_byte()])
    } else {
        String::new()
    };
    println!(
        "{}{} [{}..{}]{}",
        "  ".repeat(depth),
        node.kind(),
        node.start_byte(),
        node.end_byte(),
        text
    );
    let mut cursor = node.walk();
    for child in node.children(&mut cursor) {
        dump(child, source, depth + 1);
    }
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let src = if args.len() > 1 {
        std::fs::read_to_string(&args[1]).unwrap()
    } else {
        "x = 1;\n".to_string()
    };
    let mut parser = Parser::new();
    parser
        .set_language(&tree_sitter_matlab::LANGUAGE.into())
        .unwrap();
    let tree = parser.parse(&src, None).unwrap();
    dump(tree.root_node(), &src, 0);
}

